pub enum Error {
    NotEnoughPinsLeft,
    GameComplete,
}

pub struct BowlingGame {
    frames: Vec<Vec<u16>>,
}

impl BowlingGame {
    pub fn new() -> Self {
        BowlingGame {
            frames: vec![Vec::new(); 10],
        }
    }

    fn current_frame_index(&self) -> usize {
        for (i, frame) in self.frames.iter().enumerate().take(9) {
            if frame.is_empty() || (frame.len() == 1 && frame[0] != 10) {
                return i;
            }
        }
        9
    }

    fn is_game_complete(&self) -> bool {
        if self.current_frame_index() != 9 {
            return false;
        }
        let frame = &self.frames[9];
        match frame.len() {
            0 | 1 => false,
            2 => frame[0] != 10 && frame[0] + frame[1] != 10,
            _ => true,
        }
    }

    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {
        if pins > 10 {
            return Err(Error::NotEnoughPinsLeft);
        }
        if self.is_game_complete() {
            return Err(Error::GameComplete);
        }

        let frame_idx = self.current_frame_index();
        if frame_idx < 9 {
            let frame = &mut self.frames[frame_idx];
            if !frame.is_empty() && frame[0] + pins > 10 {
                return Err(Error::NotEnoughPinsLeft);
            }
            frame.push(pins);
        } else {
            let frame = &mut self.frames[9];
            match frame.len() {
                0 => frame.push(pins),
                1 => {
                    if frame[0] != 10 && frame[0] + pins > 10 {
                        return Err(Error::NotEnoughPinsLeft);
                    }
                    frame.push(pins);
                }
                2 => {
                    if frame[0] == 10 && frame[1] != 10 && frame[1] + pins > 10 {
                        return Err(Error::NotEnoughPinsLeft);
                    }
                    frame.push(pins);
                }
                _ => unreachable!(),
            }
        }
        Ok(())
    }

    pub fn score(&self) -> Option<u16> {
        if !self.is_game_complete() {
            return None;
        }

        let rolls: Vec<u16> = self.frames.iter().flatten().cloned().collect();
        let mut total = 0u16;
        let mut idx = 0usize;
        for _ in 0..10 {
            if rolls[idx] == 10 {
                total += 10 + rolls[idx + 1] + rolls[idx + 2];
                idx += 1;
            } else if rolls[idx] + rolls[idx + 1] == 10 {
                total += 10 + rolls[idx + 2];
                idx += 2;
            } else {
                total += rolls[idx] + rolls[idx + 1];
                idx += 2;
            }
        }
        Some(total)
    }
}
"}

