{"file_path":"hexadecimal.go","content":"// Package hexadecimal converts hexadecimal number strings to decimal.
package hexadecimal

import (
	"errors"
	"fmt"
	"math"
)

// ParseHex converts a hexadecimal string to its decimal (int64) equivalent.
func ParseHex(in string) (int64, error) {
	if len(in) == 0 {
		return 0, errors.New("syntax error: empty string")
	}

	var result int64
	for _, r := range in {
		var digit int64
		switch {
		case r >= '0' && r <= '9':
			digit = int64(r - '0')
		case r >= 'a' && r <= 'f':
			digit = int64(r-'a') + 10
		case r >= 'A' && r <= 'F':
			digit = int64(r-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid character %q", r)
		}

		if result > (math.MaxInt64-digit)/16 {
			return 0, errors.New("range error: value out of range")
		}

		result = result*16 + digit
	}

	return result, nil
}

// HandleErrors runs ParseHex over a list of inputs and classifies the
// resulting error for each into "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		case containsAny(err.Error(), "syntax"):
			results[i] = "syntax"
		case containsAny(err.Error(), "range"):
			results[i] = "range"
		default:
			results[i] = "none"
		}
	}
	return results
}

func containsAny(s, substr string) bool {
	for i := 0; i+len(substr) <= len(s); i++ {
		if s[i:i+len(substr)] == substr {
			return true
		}
	}
	return false
}
"}

