import "strings"

var animals = []string{
	"", "fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse",
}

var comments = []string{
	"",
	"",
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

func Verse(v int) string {
	var lines []string

	lines = append(lines, "I know an old lady who swallowed a "+animals[v]+".")

	if v == 8 {
		lines = append(lines, comments[v])
		return strings.Join(lines, "\n")
	}

	if comments[v] != "" {
		lines = append(lines, comments[v])
	}

	for k := v; k > 1; k-- {
		catch := "She swallowed the " + animals[k] + " to catch the " + animals[k-1]
		if animals[k-1] == "spider" {
			catch += " that wriggled and jiggled and tickled inside her"
		}
		lines = append(lines, catch+".")
	}

	lines = append(lines, "I don't know why she swallowed the fly. Perhaps she'll die.")

	return strings.Join(lines, "\n")
}

func Verses(start, end int) string {
	var verses []string
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

func Song() string {
	return Verses(1, 8)
}
"}

