HOUSES = range(5)


def _first(predicate, iterable):
    return next(filter(predicate, iterable))


def _solve():
    orderings = list(permutations(HOUSES))

    def right_of(a, b):
        return a == b + 1

    def next_to(a, b):
        return abs(a - b) == 1

    for colors in orderings:
        red, green, ivory, yellow, blue = colors
        if not right_of(green, ivory):
            continue
        for nationalities in orderings:
            english, spaniard, ukrainian, norwegian, japanese = nationalities
            if english != red:
                continue
            if norwegian != 0:
                continue
            if not next_to(norwegian, blue):
                continue
            for beverages in orderings:
                coffee, tea, milk, oj, water = beverages
                if coffee != green:
                    continue
                if ukrainian != tea:
                    continue
                if milk != 2:
                    continue
                for hobbies in orderings:
                    dancing, painter, reading, football, chess = hobbies
                    if painter != yellow:
                        continue
                    if football != oj:
                        continue
                    if japanese != chess:
                        continue
                    for pets in orderings:
                        dog, snail, fox, horse, zebra = pets
                        if spaniard != dog:
                            continue
                        if snail != dancing:
                            continue
                        if not next_to(reading, fox):
                            continue
                        if not next_to(painter, horse):
                            continue

                        nationality_by_house = {
                            english: "Englishman",
                            spaniard: "Spaniard",
                            ukrainian: "Ukrainian",
                            norwegian: "Norwegian",
                            japanese: "Japanese",
                        }
                        water_house = _first(lambda h: h == water, HOUSES)
                        zebra_house = _first(lambda h: h == zebra, HOUSES)
                        return {
                            "water": nationality_by_house[water_house],
                            "zebra": nationality_by_house[zebra_house],
                        }
    raise ValueError("No solution found")


_SOLUTION = _solve()


def drinks_water():
    return _SOLUTION["water"]


def owns_zebra():
    return _SOLUTION["zebra"]
"}

